import { PlaneGeometry, SpriteNodeMaterial, Vector2, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const tex = ctx.textureLoader(config.imageUrl);
  const img = tex.image;
  const atlasW = img.width;
  const atlasH = img.height;

  // source rect: (0, 0, 512, 320)
  const uvRepeat = new Vector2(512 / atlasW, 320 / atlasH);
  const uvOffset = new Vector2(0, 0);
  tex.repeat.copy(uvRepeat);
  tex.offset.copy(uvOffset);
  tex.wrapS = tex.wrapT = 1000; // ClampToEdgeWrapping: 1000

  const aspect = 512 / 320; // width/height
  const height = 1 / aspect;
  const geometry = new PlaneGeometry(1, height);

  const material = new SpriteNodeMaterial({
    map: tex,
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.copy(config.position);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  // no handlers, no text, no primitives
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return mesh;
}
